export fn longest_repeated_substring(p:[*]const i64,n:usize)i64{if(n<1 or n>128)return -1;const z=p[0];if(z<0 or z>127 or n!=@as(usize,@intCast(z))+1)return -1;for(0..@as(usize,@intCast(z)))|k|if(p[k+1]<0 or p[k+1]>127)return -1;var dp:[128][128]i64=@splat(@splat(0));var best:i64=0;const m:usize=@intCast(z);var i=m;i>0:{i-=1;var j=m;while(j>i+1){j-=1;if(p[i+1]==p[j+1]){dp[i][j]=1+dp[i+1][j+1];if(dp[i][j]>best)best=dp[i][j];}}}return best;}
